import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import type { Claim } from './claimsQuery';

const AMOUNT = /^\d+(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

type Body = { amount: string; date: string; note: string };

/** The one form a person's claims are added and edited through. Opening a claim's editor fills it. */
export function ClaimForm({ sheetId, personId, editing, onDone }: {
  sheetId: string;
  personId: number;
  editing: Claim | undefined;
  onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [error, setError] = useState('');

  // Opening an editor (or closing it) refills the form. A blank date is the sheet's today.
  useEffect(() => {
    setAmount(editing?.amount ?? '');
    setDate(editing?.date ?? '');
    setNote(editing?.note ?? '');
    setError('');
  }, [editing?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: Body) =>
      editing
        ? putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${editing.id}`, body, user)
        : postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/claims`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      if (editing) {
        onDone();
      } else {
        setAmount('');
        setDate('');
        setNote('');
      }
    },
    onError: (e) => setError(e instanceof RefusedError ? e.message : 'The claim could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const a = amount.trim();
    const d = date.trim();
    if (!AMOUNT.test(a)) {
      setError('The amount must be a number of 0.00 or more, with up to two decimals.');
      return;
    }
    if (d !== '' && !DATE.test(d)) {
      setError('The date must be yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync({ amount: a, date: d, note: note.trim() }));
  };

  const edit = <T,>(set: (v: T) => void) => (v: T) => {
    set(v);
    setError('');
  };

  return (
    <form data-testid="claim-form" onSubmit={submit}>
      <input
        data-testid="claim-form-amount"
        placeholder="Amount"
        value={amount}
        onChange={(e) => edit(setAmount)(e.target.value)}
      />{' '}
      <input
        data-testid="claim-form-date"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => edit(setDate)(e.target.value)}
      />{' '}
      <input
        data-testid="claim-form-note"
        placeholder="Note"
        value={note}
        onChange={(e) => edit(setNote)(e.target.value)}
      />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {error && <p data-testid="claim-form-error">{error}</p>}
    </form>
  );
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useSheetId } from './useSheetId';
import { sheetKey } from './sheetQuery';

export function SheetPicker() {
  const [sheetId, setSheetId] = useSheetId();
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState(sheetId);
  const [error, setError] = useState('');

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const id = typed.trim();
    if (id === '') {
      setError('Type a sheet id to load.');
      return;
    }
    setError('');
    // Loading a sheet always re-reads it from the store, even when it was loaded before.
    void queryClient.invalidateQueries({ queryKey: sheetKey(id) });
    setSheetId(id);
  };

  return (
    <form data-testid="sheet-form" onSubmit={submit}>
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={typed}
          onChange={(e) => {
            setTyped(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {error && <p data-testid="sheet-error">{error}</p>}
    </form>
  );
}
import { Outlet, createRootRouteWithContext } from '@tanstack/react-router';
import type { QueryClient } from '@tanstack/react-query';
import { AppNav } from '../slots/defs/appNav';

// The shell. It renders the nav region (filled from app.nav) and the matched route's component
// (from routes/); it reads no page list and holds no view state — URL search params carry what is
// open or filtered.
export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  // Search params are an open namespace, declared once here and inherited by every route: a key is
  // used by reading/writing it (url/useSearchParam), with no per-key schema.
  validateSearch: (search: Record<string, unknown>) => search,
  component: AppShell,
});

function AppShell() {
  return (
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        <AppNav.Slot />
      </nav>
      <main data-testid="app-home">
        <Outlet />
      </main>
    </div>
  );
}
