def ins(p, after, name, cls):
    s=open(p).read()
    # find step `after`, retarget its next to name, and insert new step after its block
    lines=s.split('\n'); out=[]; i=0
    while i<len(lines):
        out.append(lines[i])
        if lines[i]==after+':':
            i+=1
            while i<len(lines) and lines[i].startswith('  '):
                if lines[i].startswith('  next: '):
                    nxt=lines[i][8:]; out.append('  next: '+name)
                else: out.append(lines[i])
                i+=1
            out += [name+':','  class: '+cls,'  next: '+nxt,'  govern: [ transaction ]']
            continue
        i+=1
    open(p,'w').write('\n'.join(out))
